constexpr int CAP = 100;
struct SeqList { int data[CAP]; int length = 0; };
bool insertAt(SeqList& L, int pos, int x) {
    if (pos < 1 || pos > L.length + 1 || L.length == CAP)
        return false;
    const int k = pos - 1;
    for (int j = L.length; j > k; --j)
        L.data[j] = L.data[j - 1];
    L.data[k] = x;
    ++L.length;
    return true;
}
