bool eraseAt(SeqList& L, int pos, int& removed) {
    if (pos < 1 || pos > L.length) return false;
    const int k = pos - 1;
    removed = L.data[k];
    for (int j = k; j + 1 < L.length; ++j)
        L.data[j] = L.data[j + 1];
    --L.length;
    return true;
}
