void reverseList(Node *L) {       // 带头结点
    Node *prev=NULL, *cur=L->next;
    while (cur!=NULL) {
        Node *nxt=cur->next;
        cur->next=prev;
        prev=cur;
        cur=nxt;
    }
    L->next=prev;
}
