struct Node { int data; Node* next; };
// 返回第pos个结点；pos=0返回有效头结点。
Node* nodeAt(Node* L, int pos) {
    if (pos < 0) return nullptr;
    Node* p = L;
    while (p != nullptr && pos > 0) {
        p = p->next;
        --pos;
    }
    return p;
}
\end{codeblock}

