bool insertNode(Node* L, int pos, int x) {
    if (pos < 1) return false;
    Node* p = nodeAt(L, pos - 1);
    if (p == nullptr) return false;
    Node* s = new Node{x, p->next};
    p->next = s;
    return true;
}
bool eraseNode(Node* L, int pos, int& removed) {
    if (pos < 1) return false;
    Node* p = nodeAt(L, pos - 1);
    if (p == nullptr || p->next == nullptr) return false;
    Node* q = p->next;
    removed = q->data;
    p->next = q->next;
    delete q;
    return true;
}
\end{codeblock}

